using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsPinGizmoOperations:RefCounted
{
    private readonly PhysicsSettingsOperations _settings=new();private static Node Spatial(RefCounted owner)=>owner.Get("spatial").As<Node>();private static Node Editor(RefCounted owner)=>Spatial(owner).Get("editor").As<Node>();private static Control Gizmo(RefCounted owner)=>Spatial(owner).Get("gizmo").As<Control>();private static Node3D? Runtime(RefCounted owner)=>Spatial(owner).Call("primary").As<Node3D>();private static Resource Actor(Node runtime)=>runtime.Get("actor").As<Resource>();
    public bool active(RefCounted owner){var runtime=Runtime(owner);if(runtime==null)return false;var actor=Actor(runtime);if(!actor.GetMeta("editor_physics_pin_mode",false).AsBool()||!Editor(owner).Get("physics").AsGodotObject().Get("prototypes").AsGodotDictionary().ContainsKey(actor.Get("id")))return false;int type=_settings.authored(actor)["type"].AsInt32();return type is 1 or 4 or 5;}
    public Vector3[] points(RefCounted owner){var states=Editor(owner).Get("physics").AsGodotObject().Get("display_states").AsGodotDictionary();return states.TryGetValue(Actor(Runtime(owner)!).Get("id"),out var state)&&state.AsGodotDictionary().TryGetValue("points",out var points)?points.AsVector3Array():Array.Empty<Vector3>();}
    public void draw(RefCounted owner){if(!active(owner))return;var actor=Actor(Runtime(owner)!);var config=_settings.authored(actor);var selected=new HashSet<int>();foreach(var item in config["pins"].AsGodotArray()){var pin=item.AsGodotDictionary();selected.Add(pin.TryGetValue("point",out var id)?id.AsInt32():-1);}var positions=points(owner);var spatial=Spatial(owner);var lens=spatial.Call("camera").As<Camera3D>();var gizmo=Gizmo(owner);for(int i=0;i<positions.Length;i++){if(lens.IsPositionBehind(positions[i]))continue;var point=spatial.Call("project",positions[i]).AsVector2();gizmo.DrawCircle(point,5,new Color("10212d"));gizmo.DrawCircle(point,3.5f,new Color(selected.Contains(i)?"ffd078":"80dbc4"));if(selected.Contains(i))gizmo.DrawString(ThemeDB.FallbackFont,point+new Vector2(6,-6),i.ToString(),HorizontalAlignment.Left,-1,11,new Color("ffd078"));}gizmo.DrawString(ThemeDB.FallbackFont,new Vector2(12,30),"Point pins · Click to pin · Ctrl-click to remove · Esc to finish",HorizontalAlignment.Left,-1,12,new Color("e3f1f3"));}
    public bool handle_event(RefCounted owner,InputEvent input){if(!active(owner))return false;var actor=Actor(Runtime(owner)!);var gizmo=Gizmo(owner);if(input is InputEventKey key&&key.Pressed&&key.Keycode==Key.Escape){actor.SetMeta("editor_physics_pin_mode",false);gizmo.QueueRedraw();return true;}if(input is not InputEventMouseButton click||click.ButtonIndex!=MouseButton.Left)return false;if(!click.Pressed)return true;var positions=points(owner);float best=12;int chosen=-1;var spatial=Spatial(owner);var lens=spatial.Call("camera").As<Camera3D>();for(int i=0;i<positions.Length;i++){if(lens.IsPositionBehind(positions[i]))continue;float distance=spatial.Call("project",positions[i]).AsVector2().DistanceTo(click.Position);if(distance<best){best=distance;chosen=i;}}if(chosen>=0)_settings.pin((Control)Editor(owner),actor,chosen,positions[chosen],click.CtrlPressed);gizmo.GrabFocus();gizmo.QueueRedraw();return true;}
}
